"""离线挑战凭证的导出（challenge-export）与校验（challenge-verify）。

challenge-export 复用与 challenge 相同的确定性选样，按全局块序重读 root 下
被抽中的分块，生成自包含的 JSON 凭证（format=state-proof-challenge）并原子写入
--output；不接触任何状态文件。challenge-verify 不访问 root、不写任何文件，
仅凭证明重建选样，逐条核对证据的字段、顺序、Base64、长度与摘要，重建议定与
challenge_id，任何不一致均判 ResponseFormatError。

证据条目的 retrieval_status：
- ok：完整读回 size 字节，data 为原块 Base64，digest 为实际 BLAKE2b-256；
- missing：文件缺失/非普通文件/读失败，retrieved_size=0，digest=data=null；
- partial：短读，data 为短块 Base64，digest 为短块实际摘要。

判定优先级与 challenge 一致：missing→retrieval_missing；
partial 或摘要不符→content_mismatch；全部一致→none。
"""

import base64
import binascii
import json
import os
import stat

from .atomicio import atomic_write_json
from .challenge import _challenge_id, _flatten_chunks, _resolve_path, select_indices
from .errors import InputError, ResponseFormatError
from .hashes import blake2b_hex
from .manifest import scan_root

VERSION = 1
CHALLENGE_FORMAT = "state-proof-challenge"
_VALID_REASONS = {"none", "retrieval_missing", "content_mismatch"}
_STATUSES = {"ok", "missing", "partial"}


def _judge(statuses_match):
    """statuses_match: [(status, digest_matches_expected)] → (valid, failure_reason)。"""
    if any(status == "missing" for status, _ in statuses_match):
        return False, "retrieval_missing"
    if any(status == "partial" or not match for status, match in statuses_match):
        return False, "content_mismatch"
    return True, "none"


def _read_chunk(root, rel, offset, size):
    """读取一个分块，返回 (status, data|None)；OSError/非普通文件一律 missing。"""
    abs_path = _resolve_path(root, rel)
    try:
        st = os.lstat(abs_path)
        if not stat.S_ISREG(st.st_mode):
            return "missing", None
        with open(abs_path, "rb") as fh:
            fh.seek(offset)
            data = fh.read(size)
    except OSError:
        return "missing", None
    if len(data) == size:
        return "ok", data
    return "partial", data


def run_challenge_export(proof, root, seed, samples, output_path):
    """生成离线挑战凭证并原子写入 output_path，返回 stdout 摘要 dict。"""
    scan_root(root)  # root 不存在/非目录/不可读/扫描失败 → RootUnavailable
    if seed is None or str(seed) == "":
        raise InputError("缺少 --seed 或 seed 为空")
    seed_text = str(seed)

    flat = _flatten_chunks(proof)
    chosen = select_indices(len(flat), samples, proof["proof_id"], seed_text)

    chunk_size = proof["chunk_size"]
    evidence = []
    statuses_match = []
    for gi in chosen:
        fe, chunk_idx, _ = flat[gi]
        chunk = fe["chunks"][chunk_idx]
        offset = chunk_idx * chunk_size
        size = chunk["size"]
        status, data = _read_chunk(root, fe["path"], offset, size)
        digest = blake2b_hex(data) if data is not None else None
        evidence.append(
            {
                "path": fe["path"],
                "chunk_index": chunk_idx,
                "offset": offset,
                "size": size,
                "retrieval_status": status,
                "retrieved_size": len(data) if data is not None else 0,
                "digest": digest,
                "data": base64.b64encode(data).decode("ascii")
                if data is not None
                else None,
            }
        )
        statuses_match.append((status, digest == chunk["digest"]))

    valid, failure_reason = _judge(statuses_match)
    challenge_id = _challenge_id(
        proof["proof_id"], seed_text, samples, chosen, valid, failure_reason
    )
    response = {
        "version": VERSION,
        "format": CHALLENGE_FORMAT,
        "proof_id": proof["proof_id"],
        "challenge_id": challenge_id,
        "seed": seed_text,
        "samples": samples,
        "valid": valid,
        "failure_reason": failure_reason,
        "evidence": evidence,
    }
    atomic_write_json(output_path, response)

    return {
        "proof_id": proof["proof_id"],
        "challenge_id": challenge_id,
        "seed": seed_text,
        "samples": samples,
        "valid": valid,
        "failure_reason": failure_reason,
        "output": output_path,
    }


def _load_response(path):
    if not isinstance(path, str) or not path:
        raise ResponseFormatError("response 路径为空")
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except FileNotFoundError as exc:
        raise ResponseFormatError(f"响应文件不存在: {path}") from exc
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ResponseFormatError(f"响应文件不可解析: {path}: {exc}") from exc
    if not isinstance(data, dict):
        raise ResponseFormatError("响应顶层结构必须是对象")
    return data


def _is_hex32(value):
    return isinstance(value, str) and len(value) == 64 and all(
        c in "0123456789abcdef" for c in value
    )


def _nonneg_int(value):
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _decode_data(value, index):
    """校验 Base64 字符串并解码；非法抛 ResponseFormatError。"""
    if not isinstance(value, str):
        raise ResponseFormatError(f"evidence[{index}].data 必须是 Base64 字符串")
    try:
        return base64.b64decode(value, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ResponseFormatError(f"evidence[{index}].data 不是合法 Base64") from exc


def _check_evidence_entry(entry, index, fe, chunk_idx, chunk_size):
    """逐字段核对一条证据，返回 (status, digest_matches_expected)。"""
    where = f"evidence[{index}]"
    if not isinstance(entry, dict):
        raise ResponseFormatError(f"{where} 必须是对象")
    chunk = fe["chunks"][chunk_idx]
    # 顺序唯一：第 index 条必须恰好对应重建选样的第 index 个全局分块。
    if entry.get("path") != fe["path"] or entry.get("chunk_index") != chunk_idx:
        raise ResponseFormatError(
            f"{where} 的 path/chunk_index 与重建选样顺序不符"
        )
    if entry.get("offset") != chunk_idx * chunk_size:
        raise ResponseFormatError(f"{where}.offset 与块偏移不符")
    if entry.get("size") != chunk["size"]:
        raise ResponseFormatError(f"{where}.size 与证明块长不符")

    status = entry.get("retrieval_status")
    if status not in _STATUSES:
        raise ResponseFormatError(f"{where}.retrieval_status 非法")
    retrieved_size = entry.get("retrieved_size")
    if not _nonneg_int(retrieved_size):
        raise ResponseFormatError(f"{where}.retrieved_size 非法")

    if status == "missing":
        if retrieved_size != 0:
            raise ResponseFormatError(f"{where} missing 但 retrieved_size 非 0")
        if entry.get("digest") is not None or entry.get("data") is not None:
            raise ResponseFormatError(f"{where} missing 时 digest/data 必须为 null")
        return status, False

    raw = _decode_data(entry.get("data"), index)
    if len(raw) != retrieved_size:
        raise ResponseFormatError(f"{where}.retrieved_size 与 data 长度不符")
    if status == "ok" and retrieved_size != chunk["size"]:
        raise ResponseFormatError(f"{where} ok 但长度不等于块长")
    if status == "partial" and not retrieved_size < chunk["size"]:
        raise ResponseFormatError(f"{where} partial 但长度不短于块长")
    digest = entry.get("digest")
    if not _is_hex32(digest):
        raise ResponseFormatError(f"{where}.digest 非法")
    if digest != blake2b_hex(raw):
        raise ResponseFormatError(f"{where}.digest 与 data 实际摘要不符")
    return status, digest == chunk["digest"]


def run_challenge_verify(proof, response_path):
    """校验离线挑战凭证，返回判定 dict；任何不合法抛 ResponseFormatError。"""
    resp = _load_response(response_path)

    if resp.get("version") != VERSION:
        raise ResponseFormatError(f"不支持的响应版本: {resp.get('version')!r}")
    if resp.get("format") != CHALLENGE_FORMAT:
        raise ResponseFormatError(f"响应格式标识非法: {resp.get('format')!r}")
    if resp.get("proof_id") != proof["proof_id"]:
        raise ResponseFormatError("响应 proof_id 与证明不一致")
    seed = resp.get("seed")
    if not isinstance(seed, str) or seed == "":
        raise ResponseFormatError("响应 seed 非法")
    samples = resp.get("samples")
    if not _nonneg_int(samples) or samples <= 0:
        raise ResponseFormatError("响应 samples 必须是正整数")
    valid = resp.get("valid")
    if not isinstance(valid, bool):
        raise ResponseFormatError("响应 valid 非法")
    failure_reason = resp.get("failure_reason")
    if failure_reason not in _VALID_REASONS:
        raise ResponseFormatError("响应 failure_reason 非法")
    if valid != (failure_reason == "none"):
        raise ResponseFormatError("响应 valid 与 failure_reason 矛盾")
    challenge_id = resp.get("challenge_id")
    if not _is_hex32(challenge_id):
        raise ResponseFormatError("响应 challenge_id 非法")
    evidence = resp.get("evidence")
    if not isinstance(evidence, list):
        raise ResponseFormatError("响应 evidence 必须是数组")

    # 仅凭证明重建选样；无分块或 samples 越界 → ChallengeRangeError。
    flat = _flatten_chunks(proof)
    chosen = select_indices(len(flat), samples, proof["proof_id"], seed)
    if len(evidence) != len(chosen):
        raise ResponseFormatError(
            f"evidence 数量 {len(evidence)} 与重建选样 {len(chosen)} 不符"
        )

    statuses_match = []
    for i, gi in enumerate(chosen):
        fe, chunk_idx, _ = flat[gi]
        statuses_match.append(
            _check_evidence_entry(evidence[i], i, fe, chunk_idx, proof["chunk_size"])
        )

    # 重建议定与 challenge_id，响应声明必须与之完全一致。
    rebuilt_valid, rebuilt_reason = _judge(statuses_match)
    if valid != rebuilt_valid or failure_reason != rebuilt_reason:
        raise ResponseFormatError("响应判定与证据重建结果不一致")
    expected_id = _challenge_id(
        proof["proof_id"], seed, samples, chosen, rebuilt_valid, rebuilt_reason
    )
    if challenge_id != expected_id:
        raise ResponseFormatError("响应 challenge_id 与重建结果不一致")

    return {
        "proof_id": proof["proof_id"],
        "challenge_id": challenge_id,
        "seed": seed,
        "samples": samples,
        "valid": rebuilt_valid,
        "failure_reason": rebuilt_reason,
        "verdict": "valid" if rebuilt_valid else "invalid",
    }

"""错误类型。CLI 据此输出 error.type 并以退出码 2 退出。"""


class StateProofError(Exception):
    """所有 stateproof 受控错误的基类。"""

    type = "InputError"

    def __init__(self, message, *, details=None):
        super().__init__(message)
        self.message = message
        self.details = details or {}

    def to_dict(self):
        d = {"type": self.type, "message": self.message}
        if self.details:
            d["details"] = self.details
        return d


class InputError(StateProofError):
    """参数非法（缺少必需参数、样本数非正整数等）。"""

    type = "InputError"


class RootUnavailable(StateProofError):
    """root 不可用（不存在、不是目录、无法遍历/读取）。"""

    type = "RootUnavailable"


class ProofFormatError(StateProofError):
    """证明文件缺失、不可解析或结构/字段不合法。"""

    type = "ProofFormatError"


class ChallengeRangeError(StateProofError):
    """挑战越界：无文件可抽样，或请求样本数超过可抽样分块总数。"""

    type = "ChallengeRangeError"


class ResponseFormatError(StateProofError):
    """挑战响应文件缺失、不可解析，或版本/格式/证据/重建/challenge_id 不合法。"""

    type = "ResponseFormatError"


class StateConflict(StateProofError):
    """状态冲突：状态文件不属于该 proof_id，或结构非法无法继续。"""

    type = "StateConflict"

"""JSON 原子写入：同目录临时文件 + fsync + os.replace。

任何失败都不会在目标路径留下部分写入的内容；失败统一抛 InputError。
"""

import json
import os
import tempfile

from .errors import InputError


def atomic_write_json(path, data, *, indent=2):
    directory = os.path.dirname(os.path.abspath(path))
    try:
        os.makedirs(directory, exist_ok=True)
    except OSError as exc:
        raise InputError(f"无法创建输出目录: {path}: {exc}") from exc

    payload = json.dumps(data, ensure_ascii=False, indent=indent) + "\n"
    tmp = None
    try:
        fd, tmp = tempfile.mkstemp(
            dir=directory,
            prefix="." + os.path.basename(path) + ".",
            suffix=".tmp",
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                fh.write(payload)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp, path)
        except OSError:
            raise
    except OSError as exc:
        if tmp is not None:
            try:
                os.unlink(tmp)
            except OSError:
                pass
        raise InputError(f"无法原子写入文件: {path}: {exc}") from exc

"""证明文件的生成、读取与校验。

扫描规则：以 ``--root`` 为根递归收集**普通文件**（``S_ISREG``，跟随用户显式给出的
目录但不收符号链接本身），按 POSIX 相对路径（``/`` 分隔）排序。空目录、符号链接、
FIFO/套接字/设备等非普通文件一律忽略，文件名中任何字符（含换行、空格、Unicode）
都按字节原样参与，不改变结果。
"""

import json
import os
import stat

from .errors import ProofFormatError, RootUnavailable
from .hashes import (
    CHUNK_SIZE,
    DIGEST,
    file_digest_from_chunk_hashes,
    hash_file_chunks,
    merkle_root,
)

VERSION = 1
PROOF_FORMAT = "state-proof"


def _iter_regular_files(root):
    """生成 (POSIX 相对路径, 绝对路径)，仅普通文件；顺序由调用方排序。

    用 lstat 判型：符号链接（无论指向什么）、FIFO、套接字、设备等一律排除。
    """
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        for name in filenames:
            abs_path = os.path.join(dirpath, name)
            try:
                st = os.lstat(abs_path)
            except OSError:
                continue
            if not stat.S_ISREG(st.st_mode):
                continue
            rel = os.path.relpath(abs_path, root)
            yield rel.replace(os.sep, "/"), abs_path


def scan_root(root):
    """返回排序后的 [(rel_posix, abs_path)]；root 不可用时抛 RootUnavailable。"""
    if not isinstance(root, str) or not root:
        raise RootUnavailable("root 路径为空")
    if not os.path.exists(root):
        raise RootUnavailable(f"root 不存在: {root}")
    if not os.path.isdir(root):
        raise RootUnavailable(f"root 不是目录: {root}")
    if not os.access(root, os.R_OK | os.X_OK):
        raise RootUnavailable(f"root 不可访问: {root}")

    files = list(_iter_regular_files(root))
    files.sort(key=lambda item: item[0].encode("utf-8"))
    return files


def build_proof(root):
    """扫描 root 并构造证明 dict（含文件/分块/根摘要）。"""
    files = scan_root(root)
    file_entries = []
    root_entries = []
    for rel, abs_path in files:
        try:
            with open(abs_path, "rb") as fh:
                chunk_hashes, size = hash_file_chunks(fh)
        except OSError as exc:
            raise RootUnavailable(f"文件无法读取: {rel}: {exc}") from exc
        file_hash = file_digest_from_chunk_hashes(chunk_hashes)
        chunks = _chunks_with_sizes(size, chunk_hashes)
        file_entries.append(
            {
                "path": rel,
                "size": size,
                "digest": file_hash,
                "chunks": chunks,
            }
        )
        root_entries.append((rel, file_hash))
    root_hash = merkle_root(root_entries)
    return {
        "version": VERSION,
        "format": PROOF_FORMAT,
        "hash_algorithm": DIGEST,
        "chunk_size": CHUNK_SIZE,
        "proof_id": root_hash,
        "root": root_hash,
        "file_count": len(file_entries),
        "files": file_entries,
    }


def _chunks_with_sizes(total_size, chunk_hashes):
    """根据总大小与分块数推导每块大小：除最后一块外均为 CHUNK_SIZE。"""
    chunks = []
    n = len(chunk_hashes)
    for i, ch in enumerate(chunk_hashes):
        if i == n - 1:
            size = total_size - (n - 1) * CHUNK_SIZE if n else total_size
        else:
            size = CHUNK_SIZE
        chunks.append({"index": i, "size": size, "digest": ch})
    return chunks


def load_proof(path):
    """读取并严格校验证明文件，返回规范化 dict；非法时抛 ProofFormatError。"""
    if not isinstance(path, str) or not path:
        raise ProofFormatError("proof 路径为空")
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except FileNotFoundError as exc:
        raise ProofFormatError(f"证明文件不存在: {path}") from exc
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ProofFormatError(f"证明文件不可解析: {path}: {exc}") from exc

    if not isinstance(data, dict):
        raise ProofFormatError("证明顶层结构必须是对象")
    if data.get("version") != VERSION:
        raise ProofFormatError(f"不支持的证明版本: {data.get('version')!r}")
    if data.get("format") != PROOF_FORMAT:
        raise ProofFormatError(f"证明格式标识非法: {data.get('format')!r}")
    if data.get("hash_algorithm") != DIGEST:
        raise ProofFormatError(f"不支持的摘要算法: {data.get('hash_algorithm')!r}")
    if data.get("chunk_size") != CHUNK_SIZE:
        raise ProofFormatError(f"分块大小非法: {data.get('chunk_size')!r}")

    files = data.get("files")
    if not isinstance(files, list):
        raise ProofFormatError("files 必须是数组")

    proof_id = data.get("proof_id")
    if not isinstance(proof_id, str) or not _is_hex32(proof_id):
        raise ProofFormatError("proof_id 缺失或不是 64 位小写十六进制")
    root = data.get("root")
    if not isinstance(root, str) or not _is_hex32(root):
        raise ProofFormatError("root 摘要缺失或不是 64 位小写十六进制")

    norm_files = []
    seen = set()
    for idx, fe in enumerate(files):
        if not isinstance(fe, dict):
            raise ProofFormatError(f"files[{idx}] 必须是对象")
        rel = fe.get("path")
        if not isinstance(rel, str) or not rel:
            raise ProofFormatError(f"files[{idx}].path 非法")
        if rel in seen:
            raise ProofFormatError(f"files[{idx}] 路径重复: {rel}")
        seen.add(rel)
        if not _nonneg_int(fe.get("size")):
            raise ProofFormatError(f"files[{idx}].size 非法")
        digest = fe.get("digest")
        if not isinstance(digest, str) or not _is_hex32(digest):
            raise ProofFormatError(f"files[{idx}].digest 非法")
        chunks = fe.get("chunks")
        if not isinstance(chunks, list):
            raise ProofFormatError(f"files[{idx}].chunks 必须是数组")
        norm_chunks = []
        for ci, ch in enumerate(chunks):
            if not isinstance(ch, dict):
                raise ProofFormatError(f"files[{idx}].chunks[{ci}] 必须是对象")
            if ch.get("index") != ci:
                raise ProofFormatError(f"files[{idx}].chunks[{ci}].index 不连续")
            if not _nonneg_int(ch.get("size")):
                raise ProofFormatError(f"files[{idx}].chunks[{ci}].size 非法")
            cd = ch.get("digest")
            if not isinstance(cd, str) or not _is_hex32(cd):
                raise ProofFormatError(f"files[{idx}].chunks[{ci}].digest 非法")
            norm_chunks.append({"index": ci, "size": ch["size"], "digest": cd})
        expected_chunks = _expected_chunk_count(fe["size"])
        if len(norm_chunks) != expected_chunks:
            raise ProofFormatError(
                f"files[{idx}] 分块数 {len(norm_chunks)} 与大小 {fe['size']} 不符"
            )
        # 每块大小必须与总大小自洽：除最后一块外都是 CHUNK_SIZE，末块为余数（>0）。
        for ci, ch in enumerate(norm_chunks):
            want_size = (
                CHUNK_SIZE
                if ci < expected_chunks - 1
                else fe["size"] - ci * CHUNK_SIZE
            )
            if ch["size"] != want_size:
                raise ProofFormatError(
                    f"files[{idx}].chunks[{ci}].size 与文件总大小不符"
                )
        norm_files.append(
            {"path": rel, "size": fe["size"], "digest": digest, "chunks": norm_chunks}
        )

    # 路径必须有序，且 proof_id/root 必须与内容重算结果一致——防止手改证明。
    paths = [fe["path"] for fe in norm_files]
    if paths != sorted(paths, key=lambda p: p.encode("utf-8")):
        raise ProofFormatError("files 未按 POSIX 相对路径排序")
    for fe in norm_files:
        recomputed = file_digest_from_chunk_hashes(
            [ch["digest"] for ch in fe["chunks"]]
        )
        if recomputed != fe["digest"]:
            raise ProofFormatError(f"文件摘要与分块摘要不一致: {fe['path']}")
    recomputed_root = merkle_root([(fe["path"], fe["digest"]) for fe in norm_files])
    if recomputed_root != root:
        raise ProofFormatError("root 摘要与文件清单重算结果不一致")
    if proof_id != root:
        raise ProofFormatError("proof_id 必须与 root 摘要一致")

    if not _nonneg_int(data.get("file_count")) or data["file_count"] != len(
        norm_files
    ):
        raise ProofFormatError("file_count 与文件清单不一致")

    return {
        "version": VERSION,
        "format": PROOF_FORMAT,
        "hash_algorithm": DIGEST,
        "chunk_size": CHUNK_SIZE,
        "proof_id": proof_id,
        "root": root,
        "file_count": len(norm_files),
        "files": norm_files,
    }


def _expected_chunk_count(size):
    if size == 0:
        return 0
    return (size + CHUNK_SIZE - 1) // CHUNK_SIZE


def _nonneg_int(value):
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _is_hex32(value):
    if len(value) != 64:
        return False
    return all(c in "0123456789abcdef" for c in value)

